const response = JSON.parse($input.first().json.choices[0].message.content);
const prev = $('Parse Fact Check').first().json;
return [{ json: { ...prev, metadata: response } }];

const topicId = String($('Parse Metadata').first().json.topic_id).padStart(3, '0');
const script = $('Parse Metadata').first().json.script;
const lines = [
  { text: script.hook, start: 0, end: 4 },
  { text: script.fact, start: 4, end: 18 },
  { text: script.example, start: 18, end: 28 },
  { text: script.cta, start: 28, end: 33 }
];

let srt = '';
lines.forEach((line, i) => {
  const startH = String(Math.floor(line.start / 3600)).padStart(2, '0');
  const startM = String(Math.floor((line.start % 3600) / 60)).padStart(2, '0');
  const startS = String(line.start % 60).padStart(2, '0');
  const endH = String(Math.floor(line.end / 3600)).padStart(2, '0');
  const endM = String(Math.floor((line.end % 3600) / 60)).padStart(2, '0');
  const endS = String(line.end % 60).padStart(2, '0');
  srt += `${i + 1}\n${startH}:${startM}:${startS},000 --> ${endH}:${endM}:${endS},000\n${line.text}\n\n`;
});

return [{
  json: {
    topic_id: topicId,
    srt_content: srt,
    background_path: 'assets/backgrounds/default.png',
    audio_path: `assets/audio/${topicId}_voiceover.wav`,
    subtitles_path: `assets/captions/${topicId}.srt`,
    output_path: `data/output/${topicId}_${$('Parse Metadata').first().json.original_topic.toLowerCase().replace(/[^a-z0-9]+/g, '_')}.mp4`,
    title_text: $('Parse Metadata').first().json.metadata.youtube_title.replace(' #shorts', '')
  }
}];

const now = new Date().toISOString();
const prev = $('Parse Metadata').first().json;
const render = $('Prepare Render Assets').first().json;

const csvRow = [
  prev.topic_id,
  prev.topic_id,
  prev.original_topic,
  render.output_path,
  prev.script.estimated_duration_seconds,
  prev.script.word_count,
  prev.metadata.youtube_title,
  prev.metadata.tiktok_caption,
  prev.metadata.tags.join(';'),
  'ready_for_review',
  now,
  '',
  '',
  ''
].join(',');

return [{ json: { csv_row: csvRow, topic_id: prev.topic_id, status: 'ready_for_review' } }];

// Fact check failed — mark topic for human review
const topicId = $('Parse Fact Check').first().json.topic_id;
return [{ json: { topic_id: topicId, status: 'needs_review', reason: 'Fact check failed or low confidence' } }];
